local state = GAMESTATE:GetPlayerState(PLAYER_1)
local po = state:GetPlayerOptions('ModsLevel_Song')
po:NoteSkin('CYBER')
po:Dark(.4)
state:SetPlayerOptions('ModsLevel_Song', '')
assert(po:NoteSkin() == 'CYBER', 'empty assignment preserves noteskin')
assert(po:Dark() == 0, 'empty assignment resets numeric options')
state:SetPlayerOptions('ModsLevel_Song', 'reverse')
assert(po:NoteSkin() == 'CYBER', 'assignment without skin preserves noteskin')
assert(po:Reverse() == 1 and po:Dark() == 0)
state:SetPlayerOptions('ModsLevel_Song', 'no noteskin')
assert(po:NoteSkin() == 'cel', 'explicit skin reset uses theme default')
state:SetPlayerOptions('ModsLevel_Song', 'cyber, 50% dark')
assert(po:NoteSkin() == 'cyber' and po:Dark() == .5)
return Def.Actor{}
